#!/usr/bin/env node

const amountPattern = /^\+?(?:[0-9]+(?:\.[0-9]{0,2})?|\.[0-9]{1,2})$/;
const daysPattern = /^\+?[0-9]+$/;

function fail(message) {
  process.stderr.write(`Error: ${message}\n`);
  process.exitCode = 1;
}

function parseAmountCents(text) {
  const [whole = '0', fraction = ''] = text.replace(/^\+/, '').split('.');
  return BigInt(whole || '0') * 100n + BigInt(fraction.padEnd(2, '0') || '0');
}

function formatDollars(cents) {
  return `${cents / 100n}.${(cents % 100n).toString().padStart(2, '0')}`;
}

const args = process.argv.slice(2);

if (args.length === 0) {
  fail('invoice amount is required.');
} else if (!amountPattern.test(args[0])) {
  fail('invoice amount must be a nonnegative dollar amount with at most two decimal places.');
} else if (args[1] !== '--days') {
  fail('--days is required after the invoice amount.');
} else if (args.length === 2) {
  fail('a day count is required after --days.');
} else if (!daysPattern.test(args[2])) {
  fail('--days must be a nonnegative integer.');
} else if (args.length > 3 && (args.length !== 4 || args[3] !== '--cents')) {
  fail('unexpected extra argument.');
} else {
  const amountCents = parseAmountCents(args[0]);
  const days = BigInt(args[2]);
  const product = amountCents * days;
  const feeCents = product / 400n + (product % 400n >= 200n ? 1n : 0n);
  const totalCents = amountCents + feeCents;

  process.stdout.write(`Late fee: $${formatDollars(feeCents)}  Total due: $${formatDollars(totalCents)}\n`);
  if (args[3] === '--cents') {
    process.stdout.write(`Total due in cents: ${totalCents}\n`);
  }
}
const test = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const { join } = require('node:path');

const command = join(__dirname, '..', 'bin', 'feecalc.js');

function run(...args) {
  return spawnSync(process.execPath, [command, ...args], { encoding: 'utf8' });
}

test('prints the requested fee and total in dollars', () => {
  const result = run('200', '--days', '10');
  assert.equal(result.status, 0);
  assert.equal(result.stdout, 'Late fee: $5.00  Total due: $205.00\n');
  assert.equal(result.stderr, '');
});

test('rounds the aggregate fee once, half cents up', () => {
  const cases = [
    [['1', '--days', '1'], 'Late fee: $0.00  Total due: $1.00\n'],
    [['1', '--days', '2'], 'Late fee: $0.01  Total due: $1.01\n'],
    [['1', '--days', '3'], 'Late fee: $0.01  Total due: $1.01\n'],
    [['0', '--days', '0'], 'Late fee: $0.00  Total due: $0.00\n'],
    [['0.01', '--days', '1'], 'Late fee: $0.00  Total due: $0.01\n'],
  ];

  for (const [args, expected] of cases) {
    const result = run(...args);
    assert.equal(result.status, 0, args.join(' '));
    assert.equal(result.stdout, expected, args.join(' '));
    assert.equal(result.stderr, '', args.join(' '));
  }
});

test('accepts the approved design spellings and normalizes the output', () => {
  const cases = [
    [['0001.2', '--days', '02'], 'Late fee: $0.01  Total due: $1.21\n'],
    [['.5', '--days', '+2'], 'Late fee: $0.00  Total due: $0.50\n'],
    [['+2.', '--days', '2'], 'Late fee: $0.01  Total due: $2.01\n'],
  ];

  for (const [args, expected] of cases) {
    const result = run(...args);
    assert.equal(result.status, 0, args.join(' '));
    assert.equal(result.stdout, expected, args.join(' '));
    assert.equal(result.stderr, '', args.join(' '));
  }
});

test('keeps cents exact beyond the safe integer range', () => {
  const result = run('9007199254740993.00', '--days', '2');
  assert.equal(result.status, 0);
  assert.equal(result.stdout, 'Late fee: $45035996273704.97  Total due: $9052235251014697.97\n');
  assert.equal(result.stderr, '');
});

test('rejects missing, malformed, duplicate, and extra arguments without stdout', () => {
  const cases = [
    [],
    ['200'],
    ['200', '--days'],
    ['-1', '--days', '2'],
    ['1.234', '--days', '2'],
    ['1e2', '--days', '2'],
    ['1', '--days', '-1'],
    ['1', '--days', '1.5'],
    ['1', '--days', '2', '--days', '3'],
    ['1', '--days', '2', '--unknown'],
  ];

  for (const args of cases) {
    const result = run(...args);
    assert.notEqual(result.status, 0, args.join(' '));
    assert.equal(result.stdout, '', args.join(' '));
    assert.match(result.stderr, /^Error: .+\n$/, args.join(' '));
  }
});
